const isMac=/Mac|iPhone|iPad|iPod/.test(navigator.platform||navigator.userAgent),label=isMac?"⌘K":"Ctrl K",input=document.getElementById("search")||document.getElementById("seo-search")||document.querySelector(".search-input");if(input){const e=input.closest(".search-wrap, .seo-search-wrap");if(e){const t=document.createElement("kbd");t.className="search-shortcut-kbd",t.textContent=label,e.appendChild(t),input.addEventListener("focus",()=>t.style.display="none"),input.addEventListener("blur",()=>t.style.display="")}document.addEventListener("keydown",e=>{!e.metaKey&&!e.ctrlKey||"k"!==e.key&&"K"!==e.key&&"f"!==e.key&&"F"!==e.key||("f"!==e.key&&"F"!==e.key||e.preventDefault(),input.focus(),input.select())})}